-- ============================================================================
-- Seed calendario pronostici (giornate 23-38, 128 partite).
-- Applicato su Supabase come migrazione `seed_calendario_pronostici`.
-- I nomi squadra combaciano con i team_name dei manager; le colonne
-- casa_manager/trasferta_manager vengono popolate con la UPDATE finale.
-- ============================================================================

on conflict (numero) do nothing;

on conflict (id) do nothing;

update partite p set casa_manager = m.id from managers m where m.team_name = p.casa and p.casa_manager is null;
update partite p set trasferta_manager = m.id from managers m where m.team_name = p.trasferta and p.trasferta_manager is null;
